package controle;
import conexao.Conexao;import dao.TreinadorDAO;import java.awt.*;import javax.swing.*;import javax.swing.event.*;import javax.swing.table.DefaultTableModel;import modelo.Treinador;
public class TelaTreinador extends JFrame{private final Conexao con=new Conexao();private TreinadorDAO dao;private final JTextField id=new JTextField(),nome=new JTextField(),tel=new JTextField(),email=new JTextField(),esp=new JTextField(),pesq=new JTextField();private final DefaultTableModel m=new DefaultTableModel(new String[]{"Código","Nome","Telefone","E-mail","Especialidade"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);public TelaTreinador(){setTitle("Cadastro de Treinador");setSize(800,480);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new GridLayout(6,2,5,5));id.setEditable(false);String[] l={"Código:","Nome:","Telefone:","E-mail:","Especialidade:","Pesquisar:"};JTextField[] f={id,nome,tel,email,esp,pesq};for(int i=0;i<l.length;i++){p.add(new JLabel(l[i]));p.add(f[i]);}JPanel b=new JPanel();for(String s:new String[]{"Novo","Salvar","Excluir","Fechar"}){JButton x=new JButton(s);b.add(x);if(s.equals("Novo"))x.addActionListener(e->limpar());if(s.equals("Salvar"))x.addActionListener(e->salvar());if(s.equals("Excluir"))x.addActionListener(e->excluir());if(s.equals("Fechar"))x.addActionListener(e->dispose());}JPanel n=new JPanel(new BorderLayout());n.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));n.add(p);n.add(b,BorderLayout.SOUTH);add(n,BorderLayout.NORTH);add(new JScrollPane(t));t.getSelectionModel().addListSelectionListener(e->{int r=t.getSelectedRow();if(r>=0&&!e.getValueIsAdjusting()){id.setText(m.getValueAt(r,0).toString());nome.setText(m.getValueAt(r,1).toString());tel.setText(m.getValueAt(r,2).toString());email.setText(m.getValueAt(r,3).toString());esp.setText(m.getValueAt(r,4).toString());}});pesq.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){carregar();}public void removeUpdate(DocumentEvent e){carregar();}public void changedUpdate(DocumentEvent e){carregar();}});if(con.conecta()){dao=new TreinadorDAO(con);carregar();}addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){con.desconecta();}});}private void carregar(){if(dao==null)return;try{m.setRowCount(0);for(Treinador x:dao.listar(pesq.getText()))m.addRow(new Object[]{x.getId(),x.getNome(),x.getTelefone(),x.getEmail(),x.getEspecialidade()});}catch(Exception e){erro(e);}}private void limpar(){for(JTextField x:new JTextField[]{id,nome,tel,email,esp})x.setText("");}private void salvar(){try{if(nome.getText().isBlank())throw new IllegalArgumentException("Nome é obrigatório.");Treinador x=new Treinador();x.setNome(nome.getText());x.setTelefone(tel.getText());x.setEmail(email.getText());x.setEspecialidade(esp.getText());if(id.getText().isBlank())dao.inserir(x);else{x.setId(Integer.parseInt(id.getText()));dao.atualizar(x);}carregar();limpar();}catch(Exception e){erro(e);}}private void excluir(){if(id.getText().isBlank())return;try{dao.excluir(Integer.parseInt(id.getText()));carregar();limpar();}catch(Exception e){erro(e);}}private void erro(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Erro",JOptionPane.ERROR_MESSAGE);}}
